if __name__ == "__main__":
    t = 0.0
    out = []
    for title, where, shots in S:
        t0 = t; dur = sum(s for _, s, _, _ in shots)
        m, sec = divmod(t0, 60)
        out.append("## Scene %s · %d:%04.1f · %.1f s\n\n%s\n\n| Shot | At | s | Picture | Line |\n|---|---|---|---|---|" % (title, m, sec, dur, where))
        for n, s, pic, line in shots:
            m, sec = divmod(t, 60)
            out.append("| %s | %d:%04.1f | %.2f | %s | %s |" % (n, m, sec, s, pic, line))
            t += s
        out.append("")
    if __name__ == "__main__":
        print("\n".join(out))
    print("TOTAL %.1f s, %d shots, %d lines" % (t, sum(len(x[2]) for x in S), sum(1 for x in S for y in x[2] if y[3])))
    